mapper.select:
SELECT process, pipeline, sample_class, expressed_gene_count
FROM process_${tableSuffix}_count
WHERE process = #{process}
  AND pipeline = #{pipeline}
ORDER BY sample_class ASC

SELECT process, pipeline, sample_class,
       expr_min, expr_q1, expr_median, expr_q3, expr_max
FROM process_${tableSuffix}_boxplot
WHERE process = #{process}
  AND pipeline = #{pipeline}
ORDER BY sample_class ASC

SELECT process, pipeline, sample_class,
       gene_id, intra_mean, other_mean
FROM process_${tableSuffix}_spec
WHERE process = #{process}
  AND pipeline = #{pipeline}
ORDER BY sample_class ASC, intra_mean DESC
